pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: deposit amount and attacker address seed (we fuzz an uint256 and an address)
    function testFuzz_property(uint256 depositAmount, address attackerAddr) public {
        // keep deposit in a sane range but wide
        depositAmount = bound(depositAmount, 1, 1 ether);
        // attackerAddr should not be zero (avoid burn address)
        vm.assume(attackerAddr != address(0));

        // deploy attacker helper that will re-enter on receive
        Attacker attacker = new Attacker(address(c));

        // fund the attacker externally so it can deposit
        vm.deal(address(attacker), depositAmount);

        // attacker deposits funds into C
        attacker.doDeposit{value: depositAmount}();

        // Now attacker will call withdrawAll which will trigger reentrancy if mutant is vulnerable
        // Use try/catch to allow either revert or success; we will observe state after call
        bool ok;
        try attacker.doWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property (reference holds for all inputs): after withdrawAll completes,
        // the recorded credit of the attacker (credit[attacker]) must be zero. We read it via a helper view:
        // The contract C does not expose credit mapping as public, so we check by attempting another withdraw:
        // If credit was zero, a subsequent withdrawAll should not transfer balance (and should succeed but do nothing).
        // We use address(c).balance before and after to detect leftover credit: if credit remained >0, contract
        // would still hold less funds transferred out earlier; simpler: we assert that after withdrawal, calling
        // withdrawAll again does not change address(c).balance (i.e., no further funds are sent).

        uint256 before = address(c).balance;
        // call withdrawAll from attacker again to observe whether any funds are still withdrawable
        bool ok2;
        try attacker.doWithdraw() {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        uint256 after = address(c).balance;

        // For the correct contract, after should equal before (no further funds to withdraw), so assertTrue(before == after)
        assertTrue(before == after);
    }
}

// Minimal re-entrant attacker: on receive, it attempts to call withdrawAll on C once to try to re-enter
contract Attacker {
    address payable public target;
    bool public reentered;
    constructor(address _target) payable {
        target = payable(_target);
    }

    // deposit into C
    function doDeposit() external payable {
        // forward ETH to C.deposit
        (bool ok, ) = target.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    // initiate withdrawAll from this attacker
    function doWithdraw() external returns (bool) {
        (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        return ok;
    }

    // receive will attempt a re-entrant call once
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt re-enter
            (bool ignored, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // ignore result
            ignored;
        }
    }
}

