contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(address(c)); }

    // fuzz parameters: depositor (address) and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount in a reasonable range but wide enough
        vm.assume(depositor != address(0));
        uint256 amt = bound(amount, 1, 1 ether);

        // Fund depositor and attacker
        vm.deal(depositor, amt);
        vm.deal(address(attacker), 1 ether);

        // depositor deposits amt
        vm.prank(depositor);
        c.deposit{value: amt}();

        // attacker will be the msg.sender callee when c.send/ call is executed
        // set attacker to attempt reentrancy during withdrawAll
        attacker.prepare(depositor);

        // Now call withdrawAll as depositor but send recipient as attacker by making depositor the attacker contract's target.
        // We need the withdrawAll to send to msg.sender, so we must have attacker be msg.sender. To simulate the scenario where
        // the attacker receives Ether from c when withdrawAll is invoked, we have attacker call withdrawAll (the attacker has credit because we made depositor deposit earlier, so to allow attacker to be able to withdraw we first credit attacker by setting msg.sender to depositor when depositing---but we cannot set storage externally). Instead, the distinguishing behavior can be observed by letting the depositor be the attacker contract itself.

        // So require depositor == address(attacker) for the adversarial scenario; let fuzzer vary depositor and we prune to that wide case.
        vm.assume(depositor == address(attacker));

        // Now attacker (which is also depositor) calls withdrawAll; attacker.receive() will reenter into c.withdrawAll
        vm.prank(address(attacker));
        // call withdrawAll; capture success/failure
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After completion, assert that the total Ether received by attacker (tracked inside attacker.received())
        // is <= amt. The reference contract's reentrancy guard/ordering ensures attacker cannot drain more than its credit.
        // The mutant (which moves zeroing before external call) allows reentrancy to withdraw additional funds, so
        // for some fuzzed amt this assertion will fail on the mutant.
        assertTrue(attacker.received() <= amt);
    }
}

